package com.example.homedocsregistrar.reminder;

import com.fasterxml.jackson.annotation.JsonInclude;

/**
 * Body of {@code POST /api/v1/events}. Optional fields are omitted when null: no {@code fireTime} = the start
 * of the user's working hours, no {@code nagIntervalMinutes} = no repeats, no {@code link}.
 *
 * @param externalId generated by the registrar when the suggestion/form appears; unique with {@code source},
 *                   so a retried create is answered 200 with the existing event instead of a duplicate
 * @param ref        groups the events of one document ({@code document:<id>})
 * @param fireDate   {@code yyyy-MM-dd} in the user's local calendar
 * @param fireTime   {@code HH:mm} local time, or null
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record NewEvent(long telegramUserId,
                       String source,
                       String externalId,
                       String ref,
                       String name,
                       String fireDate,
                       String fireTime,
                       Integer nagIntervalMinutes,
                       NotifierLink link) {
}
